//! Built-in creative content. Everything is generated by TidyCuts itself
//! (shaders, vector drawings, procedural text styles), so it's free to use
//! in any video.
//!
//! Each catalog is a static list the library panel shows, the properties
//! panel edits and the MCP server can list. Ids are stable strings saved in
//! project files, so never rename one.

pub mod animations;
pub mod effects;
pub mod filters;
pub mod stickers;
pub mod titles;
pub mod transitions;

/// How a parameter is shown in the properties panel.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ParamUi {
    /// Shown as 0–100% of the range.
    Percent,
    /// Shown as the raw value with a unit suffix ("°", "px", "x"…).
    Value(&'static str),
    /// On/off; stored as 0 or 1.
    Toggle,
    /// One of several named options; stored as the option's index.
    Choice(&'static [&'static str]),
}

/// One adjustable number on an effect. Its value is handed to the shader
/// as-is, in the order the parameters are listed (p0.x, p0.y, … p3.w).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ParamDef {
    pub key: &'static str,
    pub label: &'static str,
    pub min: f32,
    pub max: f32,
    pub default: f32,
    pub ui: ParamUi,
}

impl ParamDef {
    pub const fn percent(key: &'static str, label: &'static str, default: f32) -> Self {
        ParamDef {
            key,
            label,
            min: 0.0,
            max: 1.0,
            default,
            ui: ParamUi::Percent,
        }
    }

    pub const fn value(
        key: &'static str,
        label: &'static str,
        min: f32,
        max: f32,
        default: f32,
        unit: &'static str,
    ) -> Self {
        ParamDef {
            key,
            label,
            min,
            max,
            default,
            ui: ParamUi::Value(unit),
        }
    }

    pub const fn toggle(key: &'static str, label: &'static str, default: bool) -> Self {
        ParamDef {
            key,
            label,
            min: 0.0,
            max: 1.0,
            default: if default { 1.0 } else { 0.0 },
            ui: ParamUi::Toggle,
        }
    }

    pub const fn choice(
        key: &'static str,
        label: &'static str,
        options: &'static [&'static str],
        default: usize,
    ) -> Self {
        ParamDef {
            key,
            label,
            min: 0.0,
            max: (options.len() - 1) as f32,
            default: default as f32,
            ui: ParamUi::Choice(options),
        }
    }
}

/// A color an effect uses (c0 or c1 in the shader). Stored in the clip as
/// three parameters `<key>_r`, `<key>_g`, `<key>_b`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ColorDef {
    pub key: &'static str,
    pub label: &'static str,
    pub default: [f32; 4],
}

/// A thumbnail hint: which sample picture shows an item best.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Sample {
    #[default]
    Landscape,
    Sunset,
    Portrait,
    /// A swan on the grass.
    Wildlife,
    /// Young swans on the grass.
    Meadow,
    /// A cat looking into the camera.
    Pet,
    /// A cat resting.
    Nap,
    /// A dark night scene, where light and particle overlays read clearly.
    Night,
}

/// Finds a catalog item by id in any static list with an `id` field.
pub fn find<'a, T>(list: &'a [T], id: &str, get: impl Fn(&T) -> &str) -> Option<&'a T> {
    list.iter().find(|t| get(t) == id)
}

/// Category names in first-seen order.
pub fn categories<T>(list: &[T], get: impl Fn(&T) -> &'static str) -> Vec<&'static str> {
    let mut out: Vec<&'static str> = Vec::new();
    for t in list {
        let c = get(t);
        if !out.contains(&c) {
            out.push(c);
        }
    }
    out
}
